<?php
/** Slice 3 — transfers, adjustments, the ledger's rules and reversal (ledger.md "Proof": Transfers, Adjustments, The ledger's rules). Order-independent: quantities are measured as deltas. */
require __DIR__ . '/lib.php';
$w = ledger_world();
$bea = person(28); $dana = person(30); $marco = person(27); $ann = person(29); $priya = person(26, AIRPORT); $marcoA = person(27, AIRPORT);
stock_in($dana, $w['walkin'], [['ingredient' => 'L-LIME', 'qty' => 2, 'unit' => 'case', 'unit_cost' => 38], ['ingredient' => 'L-EGG', 'qty' => 1, 'unit' => 'case', 'unit_cost' => 54]], $w['produce']);
$limeDT = on_hand($w['lime'], DOWNTOWN, $w['walkin']); $eggDT = on_hand($w['egg'], DOWNTOWN, $w['walkin']);
$limeAP = on_hand($w['lime'], AIRPORT, $w['awalkin']); $limeAPsite = on_hand($w['lime'], AIRPORT); $eggAP = on_hand($w['egg'], AIRPORT);
$avgLime = avg_cost($w['lime']); $avgEgg = avg_cost($w['egg']);

echo "1. A transfer drafted, sent, received\n";
$h = page($marco, '/transfers/new')['body'];
ok(str_contains($h, 'id="transfer-form"') && str_contains($h, 'id="transfer-form-field-to_site"') && str_contains($h, 'SMOKE Airport'), 'the transfer form offers the sites Marco holds');
$h = page($marco, '/transfers/area-options?site=' . AIRPORT, ['headers' => ['HX-Request: true']])['body'];
ok(str_contains($h, '<option value="' . $w['awalkin'] . '"') && !str_contains($h, '<option value="' . $w['walkin'] . '"'), "the to-area select re-lists the Airport's areas (Pattern A)");
$r = post($marco, '/transfers/save.php', ['from_area' => $w['walkin'], 'to_site' => AIRPORT, 'to_area' => $w['awalkin'], 'lines' => json_encode([['ingredient' => 'L-LIME', 'qty' => 100, 'unit' => 'each'], ['ingredient' => 'L-EGG', 'qty' => 2, 'unit' => 'flat']])]);
$t1 = last_id('inventory_transfers');
ok($r['code'] === 302 && str_contains($r['location'], '/transfers/' . $t1) && one('SELECT status FROM inventory_transfers WHERE id = :t', ['t' => $t1]) === 'draft', 'Marco drafts Downtown Walk-in → Airport walk-in');
ok((int) one('SELECT count(*) FROM inventory_transfer_lines WHERE transfer_id = :t', ['t' => $t1]) === 2 && near(one("SELECT qty_base FROM inventory_transfer_lines WHERE transfer_id = :t AND ingredient_id = :e", ['t' => $t1, 'e' => $w['egg']]), 60), 'two lines: 100 limes and 2 flats (60 eggs)');
ok(preg_match('/^TR-/', (string) one('SELECT number FROM inventory_transfers WHERE id = :t', ['t' => $t1])) === 1 && (int) one("SELECT count(*) FROM activity_log WHERE action = 'transfer.draft' AND entity_id = :t AND scope_id = 101", ['t' => $t1]) === 1, 'numbered TR-…; transfer.draft logged at the sending site');
$r = post($marco, '/transfers/line.php', ['transfer' => $t1, 'ingredient' => $w['flour'], 'qty' => '1', 'unit' => 'bag50']);
$tl = last_id('inventory_transfer_lines');
ok($r['code'] === 302 && near(one('SELECT qty_base FROM inventory_transfer_lines WHERE id = :l', ['l' => $tl]), 22679.6185, 0.001), 'a third line: a bag of flour');
$r = post($marco, '/transfers/line.php', ['line' => $tl, 'qty' => '2', 'unit' => 'kg']);
ok($r['code'] === 302 && near(one('SELECT qty_base FROM inventory_transfer_lines WHERE id = :l', ['l' => $tl]), 2000), 'edited to 2 kg');
$r = post($marco, '/transfers/line-remove.php', ['line' => $tl]);
ok($r['code'] === 302 && (int) one('SELECT count(*) FROM inventory_transfer_lines WHERE transfer_id = :t', ['t' => $t1]) === 2, 'and removed');
$r = post($marco, '/transfers/line.php', ['transfer' => $t1, 'ingredient' => $w['lime'], 'qty' => '1', 'unit' => 'kg']);
ok($r['code'] === 422 && has($r, 'has no each-weight'), 'limes in kg: 422 in the schema\'s words');
$h = page($marco, '/transfers/' . $t1)['body'];
ok(str_contains($h, 'id="transfer-lines-table"') && str_contains($h, 'id="transfer-send-btn"') && str_contains($h, 'data-entity="inventory_transfer"'), 'the transfer view: its lines and the Send button');
$r = post($marco, '/transfers/send.php', ['transfer' => $t1]);
ok($r['code'] === 302 && one('SELECT status FROM inventory_transfers WHERE id = :t', ['t' => $t1]) === 'in_transit', 'Send → in transit');
$out = q("SELECT ingredient_id, qty_base, unit_cost_per_base FROM inventory_transactions WHERE reference_kind = 'transfer' AND reference_id = :t AND txn_type = 'transfer_out' ORDER BY ingredient_id", ['t' => $t1]);
ok(count($out) === 2, 'two transfer_out rows');
$byIng = array_column($out, null, 'ingredient_id');
ok(near($byIng[$w['lime']]['qty_base'] ?? null, -100) && near($byIng[$w['lime']]['unit_cost_per_base'] ?? null, $avgLime, 0.0001) && near($byIng[$w['egg']]['unit_cost_per_base'] ?? null, $avgEgg, 0.0001), 'each at the sender\'s running average');
ok(near(on_hand($w['lime'], DOWNTOWN, $w['walkin']), $limeDT - 100) && near(on_hand($w['lime'], AIRPORT), $limeAPsite), 'limes: 100 fewer at Downtown, none yet at Airport (in transit)');
$r = post($marco, '/transfers/line.php', ['transfer' => $t1, 'ingredient' => $w['egg'], 'qty' => '1', 'unit' => 'flat']);
ok($r['code'] === 422 && has($r, 'change only while it is a draft'), 'a line on a sent transfer: 422 in the trigger\'s words');
$r = post($marco, '/transfers/send.php', ['transfer' => $t1]);
ok($r['code'] === 422, 'sending it twice: 422');
$h = page($marco, '/transfers/' . $t1)['body'];
ok(str_contains($h, 'id="transfer-receive-form"') && str_contains($h, 'name="received[' . (int) one('SELECT id FROM inventory_transfer_lines WHERE transfer_id = :t AND ingredient_id = :l', ['t' => $t1, 'l' => $w['lime']]) . ']"'), 'in transit: Marco (Kitchen at Airport) sees the receive form with a field per line');
$hb = page($bea, '/transfers/' . $t1)['body'];
ok(!str_contains($hb, 'id="transfer-receive-form"'), 'Bea (Downtown only) sees the transfer but no receive form');
$ll = (int) one('SELECT id FROM inventory_transfer_lines WHERE transfer_id = :t AND ingredient_id = :l', ['t' => $t1, 'l' => $w['lime']]);
$r = post($bea, '/transfers/receive.php', ['transfer' => $t1]);
ok($r['code'] === 404, 'Bea cannot receive at a site she does not hold (the kit answers a site not held with 404)');
$r = post($marco, '/transfers/receive.php', ['transfer' => $t1, 'received' => [$ll => '120'], 'received_unit' => [$ll => 'each']]);
ok($r['code'] === 422 && has($r, 'More arrived than was sent'), 'receiving more than was sent: 422 in words');
$r = post($marco, '/transfers/receive.php', ['transfer' => $t1, 'received' => [$ll => '95'], 'received_unit' => [$ll => 'each']]);
ok($r['code'] === 302 && one('SELECT status FROM inventory_transfers WHERE id = :t', ['t' => $t1]) === 'received', 'Marco receives at Airport with 95 limes counted');
$in = array_column(q("SELECT ingredient_id, qty_base, unit_cost_per_base, scope_id FROM inventory_transactions WHERE reference_kind = 'transfer' AND reference_id = :t AND txn_type = 'transfer_in'", ['t' => $t1]), null, 'ingredient_id');
ok(near($in[$w['lime']]['qty_base'] ?? null, 95) && near($in[$w['egg']]['qty_base'] ?? null, 60) && (int) ($in[$w['lime']]['scope_id'] ?? 0) === AIRPORT, 'transfer_in: 95 limes and 60 eggs at Airport (an unnamed line arrives whole)');
ok(near(one('SELECT qty_received_base FROM inventory_transfer_lines WHERE id = :l', ['l' => $ll]), 95), "the line's qty_received_base 95");
ok(near(on_hand($w['lime'], AIRPORT, $w['awalkin']), $limeAP + 95) && near(on_hand($w['egg'], AIRPORT), $eggAP + 60), 'on hand at the Airport walk-in');
ok(near(avg_cost($w['lime'], AIRPORT), $avgLime, 0.0001), "Airport's average for limes = Downtown's");
$ev = q("SELECT scope_id, after FROM activity_log WHERE action = 'transfer.receive' AND entity_id = :t", ['t' => $t1])[0] ?? null;
ok($ev !== null && (int) $ev['scope_id'] === AIRPORT && str_contains((string) $ev['after'], '"qty_received_base"'), 'transfer.receive logged at the receiving site with the received per line');
$h = page($marco, '/transfers/' . $t1)['body'];
ok(str_contains($h, 'id="transfer-movements-table"') && !str_contains($h, 'id="transfer-receive-form"'), 'a received transfer shows its movements, no form');
$r = post($marco, '/transfers/receive.php', ['transfer' => $t1]);
ok($r['code'] === 422, 'receiving it twice: 422');

echo "2. Refusals and walls\n";
$r = post($dana, '/transfers/save.php', ['from_area' => $w['walkin'], 'to_site' => AIRPORT, 'to_area' => $w['awalkin']]);
ok($r['code'] === 403 && has($r, 'do not hold that site'), 'a to-site Dana does not hold: 403');
$r = post($dana, '/transfers/save.php', ['from_area' => $w['walkin'], 'to_area' => $w['walkin']]);
ok($r['code'] === 422 && has($r, 'same area'), 'from and to the same area: 422 — the CHECK\'s rule in words');
$r = post($dana, '/transfers/save.php', ['from_area' => $w['walkin'], 'to_area' => $w['awalkin']]);
ok($r['code'] === 422 && has($r, 'not an active storage area'), "a to-area of another site than the to-site: 422");
$r = post($ann, '/transfers/save.php', ['from_area' => $w['walkin'], 'to_area' => $w['dry']]);
ok($r['code'] === 403, 'a Viewer cannot draft a transfer (403)');
$r = post($priya, '/transfers/save.php', ['from_area' => $w['abar'], 'to_area' => $w['awalkin'], 'ingredient' => 'L-LIME', 'qty' => '5', 'unit' => 'each']);
$t2 = last_id('inventory_transfers');
ok($r['code'] === 302 && (int) one('SELECT scope_id FROM inventory_transfers WHERE id = :t', ['t' => $t2]) === AIRPORT, 'Priya drafts an Airport-only transfer (bar → walk-in) with its first line');
ok(page($bea, '/transfers/' . $t2)['code'] === 404, 'Bea at Downtown cannot open it (404)');
ok(!str_contains(page($bea, '/transfers/')['body'], 'id="transfer-row-' . $t2 . '"') && str_contains(page($bea, '/transfers/')['body'], 'id="transfer-row-' . $t1 . '"'), "Bea's list shows the transfer she is party to and not the Airport-only one");
$r = post($priya, '/transfers/cancel.php', ['transfer' => $t2]);
ok($r['code'] === 302 && one('SELECT status FROM inventory_transfers WHERE id = :t', ['t' => $t2]) === 'cancelled', 'Priya cancels her draft');
$r = post($priya, '/transfers/send.php', ['transfer' => $t2]);
ok($r['code'] === 422, 'a cancelled transfer does not send');

echo "3. Adjustments\n";
$r = post($bea, '/adjustments/save.php', ['area' => $w['walkin'], 'reason' => 'breakage']);
ok($r['code'] === 403, 'Bea (no counts.approve) cannot draft an adjustment: 403');
$h = page($dana, '/adjustments/new')['body'];
ok(str_contains($h, 'id="adjustment-form"') && str_contains($h, 'id="adjustment-form-field-reason"') && !str_contains($h, 'value="plate_waste"'), 'the adjustment form lists adjustment reasons only');
$r = post($dana, '/adjustments/save.php', ['area' => $w['walkin'], 'reason' => 'plate_waste']);
ok($r['code'] === 422 && has($r, 'not an adjustment reason'), 'a waste-only reason: 422 "not an adjustment reason"');
$r = post($dana, '/adjustments/save.php', ['area' => $w['walkin'], 'reason' => 'breakage', 'notes' => 'a dropped flat']);
$a1 = last_id('inventory_adjustments');
ok($r['code'] === 302 && str_contains($r['location'], '/adjustments/' . $a1) && preg_match('/^ADJ-/', (string) one('SELECT number FROM inventory_adjustments WHERE id = :a', ['a' => $a1])) === 1, 'Dana drafts ADJ-… at the Walk-in for breakage');
$r = post($dana, '/adjustments/line.php', ['adjustment' => $a1, 'ingredient' => $w['egg'], 'qty_delta' => '-1', 'unit' => 'flat']);
$al = last_id('inventory_adjustment_lines');
ok($r['code'] === 302 && near(one('SELECT qty_delta_base FROM inventory_adjustment_lines WHERE id = :l', ['l' => $al]), -30), 'a line −1 flat of eggs → qty_delta_base −30');
$r = post($dana, '/adjustments/line.php', ['adjustment' => $a1, 'ingredient' => $w['egg'], 'qty_delta' => '0', 'unit' => 'flat']);
ok($r['code'] === 422, 'a zero change: 422');
$eggBefore = on_hand($w['egg'], DOWNTOWN, $w['walkin']); $avgEgg = avg_cost($w['egg']);
$r = post($dana, '/adjustments/post.php', ['adjustment' => $a1]);
$tx = q("SELECT qty_base, unit_cost_per_base FROM inventory_transactions WHERE reference_kind = 'adjustment' AND reference_id = :a", ['a' => $a1]);
ok($r['code'] === 302 && count($tx) === 1 && near($tx[0]['qty_base'], -30) && near($tx[0]['unit_cost_per_base'], $avgEgg, 0.0001), 'Post → one adjustment row, −30 at the running cost');
ok(near(on_hand($w['egg'], DOWNTOWN, $w['walkin']), $eggBefore - 30), 'eggs 30 fewer at the Walk-in');
ok((int) one("SELECT count(*) FROM activity_log WHERE action = 'adjustment.post' AND entity_id = :a AND scope_id = 101", ['a' => $a1]) === 1, 'adjustment.post logged');
$r = post($dana, '/adjustments/line.php', ['adjustment' => $a1, 'ingredient' => $w['egg'], 'qty_delta' => '-1', 'unit' => 'each']);
ok($r['code'] === 422 && has($r, 'only while it is draft'), 'a line on a posted adjustment: 422');
$r = post($dana, '/adjustments/save.php', ['area' => $w['bar'], 'reason' => 'opening', 'ingredient' => 'L-GIN', 'qty_delta' => '10', 'unit' => 'bottle', 'unit_cost' => '18']);
$a2 = last_id('inventory_adjustments');
ok($r['code'] === 302 && near(one('SELECT qty_delta_base FROM inventory_adjustment_lines WHERE adjustment_id = :a', ['a' => $a2]), 7500) && near(one('SELECT unit_cost_per_base FROM inventory_adjustment_lines WHERE adjustment_id = :a', ['a' => $a2]), 0.024, 0.000001), 'an opening adjustment: +10 bottles of gin at $18 a bottle → 7 500 ml at $0.024 / ml');
post($dana, '/adjustments/post.php', ['adjustment' => $a2]);
ok(near(avg_cost($w['gin']), 0.024, 0.000001), "gin's average set at $0.024 / ml");
ok((int) one("SELECT count(*) FROM price_history WHERE reference_kind = 'adjustment' AND reference_id = :a AND source_kind = 'manual'", ['a' => $a2]) === 1, 'price_history source manual');
$r = post($dana, '/adjustments/save.php', ['area' => $w['walkin'], 'reason' => 'breakage', 'ingredient' => 'L-EGG', 'qty_delta' => '-1', 'unit' => 'each', 'unit_cost' => '1']);
ok($r['code'] === 422 && has($r, 'leaves at the running average'), 'a cost on a decrease: 422 — a decrease leaves at the running average');
post($dana, '/adjustments/save.php', ['area' => $w['walkin'], 'reason' => 'breakage']);
$a3 = last_id('inventory_adjustments');
$r = post($dana, '/adjustments/post.php', ['adjustment' => $a3]);
ok($r['code'] === 422 && has($r, 'has no lines'), 'posting an adjustment with no lines: 422 in the schema\'s words');
$r = post($dana, '/adjustments/cancel.php', ['adjustment' => $a3]);
ok($r['code'] === 302 && one('SELECT status FROM inventory_adjustments WHERE id = :a', ['a' => $a3]) === 'cancelled', 'a draft cancelled');
$h = page($dana, '/adjustments/')['body'];
ok(str_contains($h, 'id="adjustment-row-' . $a1 . '"') && str_contains($h, 'id="adjustment-row-' . $a2 . '"'), 'the adjustments list');
$h = page($ann, '/adjustments/' . $a2)['body'];
ok(str_contains($h, 'id="adjustment-lines-table"') && !str_contains($h, '$0.024') && !str_contains($h, '$180.00'), 'a Viewer sees the adjustment without its cost');
ok(str_contains(page($dana, '/adjustments/' . $a2)['body'], '$180.00'), 'Dana sees its value ($180.00)');

echo "4. An agent's stock_adjust — the kernel's hook\n";
$reg = json_decode(file_get_contents(dirname(__DIR__, 3) . '/mcp/action_registry.json'), true)['actions']['stock_adjust'] ?? [];
ok(($reg['approval'] ?? null) === 'deletion' && ($reg['log_event'] ?? null) === 'adjustment.post', "the registry: stock_adjust pauses as a deletion and logs adjustment.post — the kernel's hook sees that event");
agent_facts(40, 9301);
$r = agent_req('POST', '/adjustments/save.php', 40, 9301, ['area' => 'SMOKE Walk-in', 'reason' => 'spoilage', 'ingredient' => 'L-LIME', 'qty_delta' => '-3', 'unit' => 'each']);
$a4 = (int) ($r['json']['record_id'] ?? 0);
ok($r['code'] === 200 && ($r['json']['ok'] ?? false) && $a4 > 0, 'the expert drafts an adjustment under its run token (JSON, record_id)');
$r = agent_req('POST', '/adjustments/post.php', 40, 9301, ['adjustment' => $a4]);
ok($r['code'] === 200 && one('SELECT status FROM inventory_adjustments WHERE id = :a', ['a' => $a4]) === 'posted' && one("SELECT source FROM activity_log WHERE action = 'adjustment.post' AND entity_id = :a", ['a' => $a4]) === 'agent', 'its stock_adjust lands once the hook releases it: adjustment.post with source agent');

echo "5. The ledger's rules\n";
$rw = new PDO('pgsql:host=' . need('DB_HOST') . ';port=' . need('DB_PORT') . ';dbname=' . need('DB_NAME'), need('DB_USER'), need('DB_PASSWORD'), [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$msg = static function (callable $f): string { try { $f(); return ''; } catch (PDOException $e) { return $e->getMessage(); } };
$m = $msg(fn () => $rw->exec("INSERT INTO inventory_balances (ingredient_id, storage_area_id, qty_base) VALUES ({$w['oil']}, {$w['walkin']}, 5)"));
ok(str_contains($m, 'maintained only by transactions'), 'a direct INSERT into inventory_balances as the rw role: "maintained only by transactions"');
$m = $msg(fn () => $rw->exec("UPDATE inventory_transactions SET qty_base = qty_base + 1 WHERE id = (SELECT min(id) FROM inventory_transactions)"));
ok(str_contains($m, 'never changed'), 'an UPDATE of inventory_transactions: "never changed"');
$m = $msg(fn () => $rw->exec("DELETE FROM inventory_transactions WHERE id = (SELECT min(id) FROM inventory_transactions)"));
ok($m !== '', 'a DELETE of inventory_transactions is refused');
post($dana, '/adjustments/save.php', ['area' => $w['walkin'], 'reason' => 'breakage']);
$ad = last_id('inventory_adjustments');
$m = $msg(fn () => $rw->exec("INSERT INTO inventory_adjustment_lines (adjustment_id, line_no, ingredient_id, qty_delta, unit_code, qty_delta_base, unit_cost_per_base) VALUES ($ad, 1, {$w['egg']}, -1, 'each', 0, 0.5)"));
ok(str_contains($m, 'A decrease leaves at the running average'), 'db/022: a decrease line carrying a cost, inserted directly as the rw role — refused in words (the movement would have been valued at it)');
$m = $msg(fn () => $rw->exec("INSERT INTO inventory_adjustment_lines (adjustment_id, line_no, ingredient_id, qty_delta, unit_code, qty_delta_base, unit_cost_per_base) VALUES ($ad, 1, {$w['egg']}, 1, 'each', 0, 0.5)"));
ok($m === '' && near(one('SELECT qty_delta_base FROM inventory_adjustment_lines WHERE adjustment_id = :a', ['a' => $ad]), 1), '…an increase with its cost is taken');
post($dana, '/adjustments/cancel.php', ['adjustment' => $ad]);
$g = stock_in($dana, $w['dry'], [['ingredient' => 'L-OIL', 'qty' => 1, 'unit' => 'case4', 'unit_cost' => 60]]);
$tid = (int) one("SELECT id FROM inventory_transactions WHERE reference_kind = 'goods_receipt' AND reference_id = :g", ['g' => $g]);
$at = (string) one('SELECT occurred_at FROM inventory_transactions WHERE id = :t', ['t' => $tid]);
$oil = on_hand($w['oil']);
$r = post($bea, '/stock/reverse.php', ['transaction' => $tid]);
ok($r['code'] === 403, 'Bea (no counts.approve) cannot reverse a movement: 403');
$r = post($dana, '/stock/reverse.php', ['transaction' => $tid, 'note' => 'keyed twice']);
$rev = (int) one('SELECT id FROM inventory_transactions WHERE reverses_id = :t', ['t' => $tid]);
ok($r['code'] === 302 && $rev > 0 && one('SELECT txn_type FROM inventory_transactions WHERE id = :r', ['r' => $rev]) === 'reversal' && near(one('SELECT qty_base FROM inventory_transactions WHERE id = :r', ['r' => $rev]), -15141.65, 0.01), 'Dana reverses the receipt row: a reversal with the opposite quantity');
ok(near(on_hand($w['oil']), $oil - 15141.65, 0.01), 'the oil is gone again');
ok((int) one("SELECT count(*) FROM activity_log WHERE action = 'stock.reverse' AND entity_id = :t AND ingredient_id = :i", ['t' => $tid, 'i' => $w['oil']]) === 1, 'stock.reverse logged with ingredient_id');
$r = post($dana, '/stock/reverse.php', ['transaction' => $tid]);
ok($r['code'] === 422 && has($r, 'Already reversed'), 'a second reversal: 422 "Already reversed"');
$r = post($dana, '/stock/reverse.php', ['transaction' => $rev]);
ok($r['code'] === 422 && has($r, 'not reversed'), 'reversing a reversal: 422');
ok(near(one('SELECT ri_on_hand_as_of(:i, 101, :t::timestamptz - interval \'1 second\')', ['i' => $w['oil'], 't' => $at]), $oil - 15141.65, 0.01), 'ri_on_hand_as_of() just before the receipt: without it');
ok(near(one("SELECT ri_on_hand_as_of(:i, 101, now() - interval '1 second')", ['i' => $w['oil']]), $oil - 15141.65, 0.01) || near(one("SELECT ri_on_hand_as_of(:i, 101, now())", ['i' => $w['oil']]), $oil - 15141.65, 0.01), 'and now, net of the reversal (dated at the movement it reverses)');
$h = page($dana, '/stock/movements?ingredient=' . $w['oil'])['body'];
ok(str_contains($h, 'id="movement-row-' . $rev . '"') && str_contains($h, 'id="movement-row-' . $tid . '"') && !str_contains($h, 'id="movement-reverse-' . $tid . '"'), 'the movements: both rows, no Reverse on the reversed one');
$walk = on_hand($w['lime'], DOWNTOWN, $w['walkin']);
$r = post($dana, '/waste/save.php', ['stage' => 'ingredient', 'reason' => 'spoilage', 'ingredient' => $w['lime'], 'qty' => (string) ($walk + 50), 'unit' => 'each', 'area' => $w['walkin']]);
ok($r['code'] === 302 && near(on_hand($w['lime'], DOWNTOWN, $w['walkin']), -50), 'a waste larger than on hand at the Walk-in (allow_negative) takes it below zero');
$r = post($dana, '/waste/save.php', ['stage' => 'ingredient', 'reason' => 'spoilage', 'ingredient' => $w['lime'], 'qty' => '5', 'unit' => 'each', 'area' => $w['cold']]);
ok($r['code'] === 422 && has($r, 'refuses a negative balance'), 'at the Cold room (allow_negative = false): 422 in the schema\'s words');
stock_in($dana, $w['walkin'], [['ingredient' => 'L-LIME', 'qty' => 1, 'unit' => 'case', 'unit_cost' => 38]]);
finish();
